import { areas, parts } from "../glossary/glossary";

function cell(value: string): string {
  return value.replaceAll("|", "\\|").replace(/\r?\n/gu, " ");
}

/** The agent reference and viewer consume the same canonical data. */
export function renderGlossary(): string {
  const lines = [
    "# UI glossary / 용어 사전", "",
    "Always call a UI part by its Korean or English glossary name. Never use the avoided names in 이전 이름.",
    "한국어·영어 이름은 UI 부분의 공식 명칭입니다. 화면에 표시되는 문구나 코드 API를 바꾸는 지침이 아닙니다.",
    "", "Generated by `bun run ds:glossary` from `glossary/glossary.ts`. Do not edit by hand.", "",
  ];
  for (const area of areas) {
    lines.push(`## ${area.ko} / ${area.en}`, "",
      "| id | 한국어 | English | 설명 | DS | 이전 이름 |",
      "| --- | --- | --- | --- | --- | --- |");
    for (const part of parts.filter((item) => item.area === area.id)) {
      lines.push(`| ${[part.id, part.ko, part.en, part.desc, part.ds.join(", "), part.avoid.join(", ")].map(cell).join(" | ")} |`);
    }
    lines.push("");
  }
  return lines.join("\n");
}
